import Iter "mo:base/Iter";

public query func getListedNFTs() : async [Principal] {
  let ids = Iter.toArray(mapOfListings.keys());
  return ids;
};

public query func getOriginalOwner(id : Principal) : async Principal {
  var listing : Listing = switch (mapOfListings.get(id)) {
    case null return Principal.fromText("");
    case (?result) result;
  };
  return listing.itemOwner;
};

public query func getListedNFTPrice(id : Principal) : async Nat {
  var listing : Listing = switch (mapOfListings.get(id)) {
    case null return 0;
    case (?result) result;
  };
  return listing.itemPrice;
};

async function getNFTs() {
  const userNFTIds = await OPEND_backend.getOwnedNFTs(CURRENT_USER_ID);
  setOwnedGallery(<Gallery title="My NFTs" ids={userNFTIds} role="collection" />);

  const listedNFTIds = await OPEND_backend.getListedNFTs();
  setListingGallery(<Gallery title="Discover" ids={listedNFTIds} role="discover" />);
}

if (props.role == "collection") {
  const nftIsListed = await OPEND_backend.isListed(props.id);
  if (nftIsListed) {
    setOwner("OpenD");
    setBlur({ filter: "blur(4px)" });
    setSellStatus("Listed");
  } else {
    setButton(<Button handleClick={handleSell} text={"Sell"} />);
  }
} else if (props.role == "discover") {
  const originalOwner = await OPEND_backend.getOriginalOwner(props.id);
  if (originalOwner.toText() != CURRENT_USER_ID.toText()) {
    setButton(<Button handleClick={handleBuy} text={"Buy"} />);
  }
  const price = await OPEND_backend.getListedNFTPrice(props.id);
  setPriceLabel(<PriceLabel sellPrice={price.toString()} />);
}

import React from "react";

function PriceLabel(props) {
  return (
    <div className="disButtonBase-root disChip-root makeStyles-price-23 disChip-outlined">
      <span className="disChip-label">{props.sellPrice} DANG</span>
    </div>
  );
}
export default PriceLabel;
